/*
 * A362555  Number of distinct n-digit suffixes generated by iteratively
 *          multiplying an integer by 6, where the initial integer is 1.
 * https://oeis.org/A362555
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = 5^(n-1) + n
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 14, u64 n <= 28, u128 n <= 56,
 *            big any n
 * Validated: standard, pass, 41 terms through n = 814 (2026-11-01)
 * Helpers:   ipow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/ipow.h"

seq_t a(idx_t n)
{
    /* Compute 5^(n-1) and add n */
    seq_t power = ipow((seq_t)5, n-1);
    power += (seq_t)n;
    return power;
}
